  for (const [w, c] of clients) if (c.name === name) w.close(4002, 'dup');
  const me = { id: 'p' + (nextId++), name, presence: null, tok: 120, tt: Date.now() };
  clients.set(ws, me); wss.clients.add(ws); byId.set(me.id, ws);
  ws.send(JSON.stringify({ t: 'hello', id: me.id, peers: snapshot() }));
  ws.on('message', buf => { try { onWsMessage(buf); } catch (e) { console.error('ws message error', e && e.message); } });
